<script setup lang="ts">
import { ref } from "vue";
import StudentImportCredentials from "../../components/StudentImportCredentials.vue";
import { ElMessage } from "element-plus";
import { teacherGet, teacherImportStudentsFile, type ImportResult, type TeacherClass } from "../../../teacher/teacherApi";
const classes=ref<TeacherClass[]>([]);const classId=ref<number|null>(null);const studentNoField=ref("学号");const nameField=ref("姓名");const file=ref<File|null>(null);const result=ref<ImportResult|null>(null);const loading=ref(false);
async function load(){try{classes.value=await teacherGet<TeacherClass[]>("/api/teacher/v1/classes");}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"班级列表加载失败");}}
function choose(event:Event){const input=event.target as HTMLInputElement;const next=input.files?.[0]??null;if(next&&!/\.(csv|xls|xlsx)$/i.test(next.name)){ElMessage.error("仅支持 csv、xls、xlsx 文件");input.value="";return;}file.value=next;result.value=null;}
async function submit(){if(!classId.value){ElMessage.warning("请选择目标班级");return;}if(!file.value){ElMessage.warning("请选择 csv、xls 或 xlsx 文件");return;}loading.value=true;try{result.value=await teacherImportStudentsFile({classId:classId.value,studentNoField:studentNoField.value,nameField:nameField.value,file:file.value});ElMessage.success("导入完成");}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"导入失败");}finally{loading.value=false;}}
void load();
</script>
<template><section class="import-page page-container"><el-card shadow="never" class="import-card"><el-alert type="info" :closable="false" show-icon title="仅支持 CSV、XLS、XLSX。首行必须是表头，必需字段为学号和姓名；其他列将保存为学生扩展资料，不导入邮箱和手机号。"/><el-form label-position="top" class="import-form"><el-form-item label="目标班级" required><el-select v-model="classId" placeholder="选择班级"><el-option v-for="item in classes" :key="item.id" :value="item.id" :label="`${item.name}（${item.id}）`"/></el-select></el-form-item><el-form-item label="导入文件" required><input type="file" accept=".csv,.xls,.xlsx,text/csv,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" @change="choose"><span v-if="file" class="file-name">{{file.name}}</span></el-form-item><div class="two-col"><el-form-item label="学号字段" required><el-input v-model="studentNoField"/></el-form-item><el-form-item label="姓名字段" required><el-input v-model="nameField"/></el-form-item></div><p class="muted">示例表头：学号,姓名,专业,备注</p><el-button type="primary" :loading="loading" @click="submit">开始导入</el-button></el-form></el-card><el-card v-if="result" shadow="never"><template #header><strong>导入结果</strong></template><div class="result-tags"><el-tag type="success">成功 {{result.successCount}}</el-tag><el-tag type="danger">失败 {{result.failureCount}}</el-tag></div><StudentImportCredentials :successes="result.successes"/><h3>成功导入</h3><el-table :data="result.successes??[]" stripe><el-table-column prop="rowNumber" label="行号" width="90"/><el-table-column prop="studentNo" label="学号" width="150"/><el-table-column prop="displayName" label="姓名"/></el-table><h3>失败明细</h3><el-table :data="result.errors??[]" stripe><el-table-column prop="rowNumber" label="行号" width="90"/><el-table-column prop="studentNo" label="学号" width="150"/><el-table-column prop="reason" label="原因"/></el-table></el-card></section></template>
<style scoped>.import-page{display:flex;flex-direction:column;gap:16px}.page-heading h1{margin:0;font-size:22px}.page-heading p,.muted{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.import-card{max-width:840px}.import-form{margin-top:18px}.import-form .el-select{width:100%}.file-name{margin-left:8px;color:var(--el-text-color-secondary)}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px}.result-tags{display:flex;gap:8px}h3{margin:20px 0 8px;font-size:14px}@media(max-width:600px){.two-col{grid-template-columns:1fr}}</style>
